CREATE TABLE checklist_modelos (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, nome character varying NOT NULL, area character varying, periodicidade character varying DEFAULT 'diario'::character varying NOT NULL, ativo boolean DEFAULT true NOT NULL, criado_em timestamp with time zone DEFAULT now() NOT NULL, CHECK (((periodicidade)::text = ANY ((ARRAY['diario'::character varying, 'semanal'::character varying, 'mensal'::character varying, 'livre'::character varying])::text[]))), PRIMARY KEY (id), UNIQUE (id, condominio_id));
CREATE TABLE checklist_respostas (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, execucao_id uuid NOT NULL, item_id bigint NOT NULL, resposta character varying NOT NULL, observacao text, foto_data_url text, condominio_id uuid NOT NULL, PRIMARY KEY (id), CHECK (((resposta)::text = ANY ((ARRAY['ok'::character varying, 'nao_ok'::character varying, 'na'::character varying])::text[]))));
