CREATE TABLE condominios (id uuid DEFAULT gen_random_uuid() NOT NULL, cnpj character varying NOT NULL, nome character varying NOT NULL, ativo boolean DEFAULT true NOT NULL, criado_em timestamp with time zone DEFAULT now() NOT NULL, atualizado_em timestamp with time zone DEFAULT now() NOT NULL, razao_social character varying, email character varying, telefone character varying, endereco text, responsavel character varying, plano character varying DEFAULT 'profissional'::character varying NOT NULL, status character varying DEFAULT 'ativo'::character varying NOT NULL, limite_usuarios integer, modulos jsonb DEFAULT '["painel", "manutencoes", "os", "checklists", "ocorrencias", "inventario", "estoque", "ferramentas", "cotacoes", "fornecedores", "documentos", "unidades", "reservas", "comunicados", "relatorios"]'::jsonb NOT NULL, UNIQUE (cnpj), PRIMARY KEY (id), CHECK (((status)::text = ANY ((ARRAY['ativo'::character varying, 'suspenso'::character varying, 'inativo'::character varying])::text[]))));
CREATE TABLE configuracoes_sistema (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, nome_sistema character varying DEFAULT 'Gestão de Inventário e Estoque'::character varying NOT NULL, logo_data_url text, cor_primaria character varying DEFAULT '#2456d3'::character varying NOT NULL, endereco text, telefone character varying, email character varying, rodape_relatorio text, mensagem_pedido text, criado_em timestamp with time zone DEFAULT now() NOT NULL, atualizado_em timestamp with time zone DEFAULT now() NOT NULL, UNIQUE (condominio_id), PRIMARY KEY (id));
