CREATE TABLE documentos_condominio (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, titulo character varying NOT NULL, categoria character varying, numero character varying, emissao date, validade date, fornecedor_id uuid, arquivo_data_url text, observacoes text, ativo boolean DEFAULT true NOT NULL, criado_em timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
