CREATE TABLE ferramentas (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, codigo character varying, nome character varying NOT NULL, categoria character varying, marca character varying, modelo character varying, numero_serie character varying, estado_conservacao character varying DEFAULT 'bom'::character varying NOT NULL, status character varying DEFAULT 'disponivel'::character varying NOT NULL, localizacao character varying, responsavel_atual character varying, observacoes text, ativo boolean DEFAULT true NOT NULL, criado_por uuid, atualizado_por uuid, criado_em timestamp with time zone DEFAULT now() NOT NULL, atualizado_em timestamp with time zone DEFAULT now() NOT NULL, qr_token uuid DEFAULT gen_random_uuid(), UNIQUE (condominio_id, codigo), CHECK (((estado_conservacao)::text = ANY ((ARRAY['novo'::character varying, 'otimo'::character varying, 'bom'::character varying, 'regular'::character varying, 'ruim'::character varying, 'manutencao'::character varying, 'inservivel'::character varying])::text[]))), PRIMARY KEY (id), CHECK (((status)::text = ANY ((ARRAY['disponivel'::character varying, 'emprestada'::character varying, 'manutencao'::character varying, 'inservivel'::character varying])::text[]))), UNIQUE (id, condominio_id));
CREATE TABLE fornecedores (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, razao_social character varying NOT NULL, nome_fantasia character varying, cnpj character varying, contato character varying, telefone character varying, email character varying, categoria character varying, avaliacao integer, observacoes text, ativo boolean DEFAULT true NOT NULL, criado_em timestamp with time zone DEFAULT now() NOT NULL, atualizado_em timestamp with time zone DEFAULT now() NOT NULL, CHECK (((avaliacao >= 1) AND (avaliacao <= 5))), PRIMARY KEY (id), UNIQUE (id, condominio_id));
CREATE TABLE historico_inventario (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, inventario_id uuid NOT NULL, condominio_id uuid NOT NULL, usuario_id uuid, acao character varying NOT NULL, dados jsonb, criado_em timestamp with time zone DEFAULT now() NOT NULL, CHECK (((acao)::text = ANY ((ARRAY['criado'::character varying, 'editado'::character varying, 'excluido'::character varying, 'restaurado'::character varying])::text[]))), PRIMARY KEY (id));
CREATE TABLE inventario (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, patrimonio character varying, descricao character varying NOT NULL, categoria character varying, quantidade numeric DEFAULT 1 NOT NULL, unidade character varying DEFAULT 'un'::character varying NOT NULL, localizacao character varying, estado_conservacao character varying DEFAULT 'bom'::character varying NOT NULL, valor_aquisicao numeric, data_aquisicao date, foto_url text, observacoes text, ativo boolean DEFAULT true NOT NULL, criado_por uuid, atualizado_por uuid, criado_em timestamp with time zone DEFAULT now() NOT NULL, atualizado_em timestamp with time zone DEFAULT now() NOT NULL, qr_token uuid DEFAULT gen_random_uuid(), UNIQUE (condominio_id, patrimonio), CHECK (((estado_conservacao)::text = ANY ((ARRAY['novo'::character varying, 'otimo'::character varying, 'bom'::character varying, 'regular'::character varying, 'ruim'::character varying, 'inservivel'::character varying])::text[]))), PRIMARY KEY (id), CHECK ((quantidade >= (0)::numeric)), UNIQUE (id, condominio_id));
