CREATE TABLE moradores (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, unidade_id uuid NOT NULL, nome character varying NOT NULL, tipo character varying DEFAULT 'morador'::character varying NOT NULL, telefone character varying, email character varying, veiculo character varying, ativo boolean DEFAULT true NOT NULL, criado_em timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id), CHECK (((tipo)::text = ANY ((ARRAY['proprietario'::character varying, 'morador'::character varying, 'inquilino'::character varying, 'dependente'::character varying])::text[]))));
