CREATE TABLE ocorrencias (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, protocolo character varying NOT NULL, titulo character varying NOT NULL, descricao text, categoria character varying, prioridade character varying DEFAULT 'media'::character varying NOT NULL, status text DEFAULT 'aberta'::character varying NOT NULL, unidade character varying, responsavel character varying, anexos jsonb DEFAULT '[]'::jsonb NOT NULL, criado_por uuid, criado_em timestamp with time zone DEFAULT now() NOT NULL, resolvido_em timestamp with time zone, UNIQUE (condominio_id, protocolo), PRIMARY KEY (id), CHECK (((prioridade)::text = ANY ((ARRAY['baixa'::character varying, 'media'::character varying, 'alta'::character varying, 'critica'::character varying])::text[]))), CHECK ((status = ANY (ARRAY[('aberta'::character varying)::text, ('em_analise'::character varying)::text, ('em_atendimento'::character varying)::text, ('resolvida'::character varying)::text, ('arquivada'::character varying)::text]))));
CREATE TABLE ordens_servico (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, numero_os character varying NOT NULL, manutencao_plano_id uuid, inventario_id uuid, fornecedor_id uuid, titulo character varying NOT NULL, descricao text, prioridade character varying DEFAULT 'media'::character varying NOT NULL, status text DEFAULT 'aberta'::character varying NOT NULL, responsavel character varying, data_abertura timestamp with time zone DEFAULT now() NOT NULL, prazo timestamp with time zone, data_conclusao timestamp with time zone, custo_real numeric, materiais_usados text, fotos_antes jsonb DEFAULT '[]'::jsonb NOT NULL, fotos_depois jsonb DEFAULT '[]'::jsonb NOT NULL, observacoes text, criado_por uuid, atualizado_por uuid, UNIQUE (condominio_id, numero_os), PRIMARY KEY (id), CHECK (((prioridade)::text = ANY ((ARRAY['baixa'::character varying, 'media'::character varying, 'alta'::character varying, 'critica'::character varying])::text[]))), CHECK ((status = ANY (ARRAY[('aberta'::character varying)::text, ('em_andamento'::character varying)::text, ('aguardando'::character varying)::text, ('concluida'::character varying)::text, ('cancelada'::character varying)::text]))));
