CREATE TABLE pedidos_materiais_itens (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, pedido_id uuid NOT NULL, material_id uuid NOT NULL, quantidade_solicitada numeric NOT NULL, estoque_atual numeric NOT NULL, estoque_minimo numeric NOT NULL, condominio_id uuid NOT NULL, PRIMARY KEY (id), CHECK ((quantidade_solicitada > (0)::numeric)));
CREATE TABLE reservas (id uuid DEFAULT gen_random_uuid() NOT NULL, condominio_id uuid NOT NULL, area_id uuid NOT NULL, unidade_id uuid, responsavel character varying NOT NULL, inicio timestamp with time zone NOT NULL, fim timestamp with time zone NOT NULL, status text DEFAULT 'confirmada'::character varying NOT NULL, observacoes text, criado_em timestamp with time zone DEFAULT now() NOT NULL, tipo_evento character varying, email_solicitante character varying, valor_total numeric DEFAULT 0 NOT NULL, valor_pago numeric DEFAULT 0 NOT NULL, lembrete_enviado_em timestamp with time zone, atualizado_em timestamp with time zone DEFAULT now() NOT NULL, valor_restante numeric, whatsapp_solicitante character varying, PRIMARY KEY (id), CHECK ((status = ANY (ARRAY['realizada'::text, 'confirmada'::text, 'cancelada'::text]))), CHECK (((valor_pago >= (0)::numeric) AND (valor_pago <= valor_total))), CHECK ((valor_total >= (0)::numeric)));
CREATE TABLE sessoes (id uuid DEFAULT gen_random_uuid() NOT NULL, usuario_id uuid NOT NULL, token_hash text NOT NULL, expira_em timestamp with time zone NOT NULL, criado_em timestamp with time zone DEFAULT now() NOT NULL, condominio_id uuid, ip character varying, user_agent text, ultimo_acesso_em timestamp with time zone, encerrado_em timestamp with time zone, PRIMARY KEY (id), UNIQUE (token_hash));
